#!/bin/bash
# GitHub runner side of the ISO build (generated by
# rakuos-project/github-workflow-gen/iso/gen.py; edit the template there).
#
# rakuos-forge's staging install (bootc install --composefs-backend) needs a
# kernel with EROFS and fs-verity, and a running udev: GitLab's hosted
# runners have none of the three, a GitHub runner is a full VM with all of
# them. The build itself runs in a privileged Fedora container (rakuos-forge
# is a Fedora package), which shares this VM's kernel, /dev and /run/udev.
# Podman's store and /var/tmp inside it are real directories on the VM's
# disk, not the container's overlayfs.
set -euo pipefail

# Kernel features, checked up front so a missing one fails in seconds.
sudo modprobe loop || true
if ! grep -qw erofs /proc/filesystems; then
  sudo modprobe erofs || {
    sudo apt-get update -q
    sudo apt-get install -y -q "linux-modules-extra-$(uname -r)"
    sudo modprobe erofs
  }
fi
grep -qw erofs /proc/filesystems || { echo "::error::kernel $(uname -r) has no EROFS"; exit 1; }
if ! grep -q '^CONFIG_FS_VERITY=y' "/boot/config-$(uname -r)" 2>/dev/null; then
  echo "::error::kernel $(uname -r) has no fs-verity (CONFIG_FS_VERITY)"; exit 1
fi
[ -d /run/udev ] || { echo "::error::no /run/udev: udev isn't running"; exit 1; }
echo "kernel $(uname -r): EROFS and fs-verity available, udev running"

WORK=/mnt/iso
sudo mkdir -p "${WORK}/src" "${WORK}/containers" "${WORK}/tmp"
sudo chmod 1777 "${WORK}/tmp"
sudo cp -a . "${WORK}/src/"
df -h /

export BRANCH="${GITHUB_REF_NAME}"
# CI: GitHub sets it on the runner; rakuos-forge needs it inside the build
# container too, or it refuses to make the ISO in a container instead of
# installing its ISO tools ("Cannot run in nested containers").
export CI="${CI:-true}"
PASS_VARS=(
  CI BRANCH EDITION IMAGE_REPO CDN77_PATH SOURCEFORGE_DIR FORGE_MODE
  SOURCEFORGE_UPLOAD CDN77_UPLOAD
  CDN77_CDN_ID CDN77_API_KEY CDN77_ACCESS_KEY CDN77_SECRET_KEY CDN77_BUCKET CDN77_ENDPOINT_URL
  SOURCEFORGE_USERNAME SOURCEFORGE_PASSWORD SOURCEFORGE_HOST SOURCEFORGE_LATEST_PATH SOURCEFORGE_ARCHIVE_ROOT
)
env_args=()
for v in "${PASS_VARS[@]}"; do
  env_args+=(-e "${v}")
done

BUILD_IMAGE=quay.io/fedora/fedora:latest
attempt=1 delay=15
until sudo podman pull --quiet "${BUILD_IMAGE}" >/dev/null; do
  if [ "${attempt}" -ge 5 ]; then
    echo "ERROR: pulling ${BUILD_IMAGE} failed 5 times, giving up" >&2
    exit 1
  fi
  echo "Pulling ${BUILD_IMAGE} failed (attempt ${attempt}/5); retrying in ${delay}s..." >&2
  sleep "${delay}"
  attempt=$((attempt + 1))
  delay=$((delay * 2))
done

sudo --preserve-env="$(IFS=,; echo "${PASS_VARS[*]}")" podman run --rm --privileged \
  --security-opt label=disable \
  -v /dev:/dev -v /run/udev:/run/udev \
  -v "${WORK}/containers":/var/lib/containers -v "${WORK}/tmp":/var/tmp \
  -v "${WORK}/src":/src -w /src \
  "${env_args[@]}" \
  "${BUILD_IMAGE}" \
  bash .github/scripts/build-iso.sh

df -h /
